"use client";
import { useId, useState } from "react";
import "./segmented-switch.css";

/** Native radios behind a spring-eased thumb, so arrow keys and forms just work. */
export function SegmentedSwitch({
  options,
  label,
  value,
  defaultValue,
  onChange,
  name,
  className = "",
}: {
  options: string[];
  label: string;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  name?: string;
  className?: string;
}) {
  const auto = useId();
  const [own, setOwn] = useState(defaultValue ?? options[0]);
  const current = value ?? own;
  return (
    <div
      role="radiogroup"
      aria-label={label}
      className={`forme-segmented ${className}`}
      style={{
        gridTemplateColumns: `repeat(${options.length}, minmax(0, 1fr))`,
        ["--forme-segmented-count" as string]: options.length,
        ["--forme-segmented-index" as string]: Math.max(0, options.indexOf(current)),
      }}
    >
      <span className="forme-segmented-thumb" aria-hidden="true" />
      {options.map((option) => (
        <label key={option} data-active={option === current || undefined}>
          <input
            type="radio"
            name={name || auto}
            value={option}
            checked={option === current}
            onChange={() => {
              setOwn(option);
              onChange?.(option);
            }}
          />
          <span>{option}</span>
        </label>
      ))}
    </div>
  );
}

.forme-segmented {
  position: relative;
  isolation: isolate;
  display: inline-grid;
  align-self: center;
  box-sizing: border-box;
  padding: 3px;
  border-radius: 12px;
  background: #ffffff0f;
  box-shadow: inset 0 1px 2px #00000066;
  font-size: 14px;
  font-weight: 500;
}
.forme-segmented-thumb {
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 3px;
  z-index: -1;
  width: calc((100% - 6px) / var(--forme-segmented-count));
  border-radius: 9px;
  background: linear-gradient(180deg, #2a2a30, #1c1c21);
  box-shadow:
    inset 0 1px 0 #ffffff1f,
    0 2px 6px #00000080;
  transform: translateX(calc(100% * var(--forme-segmented-index)));
  transition: transform 0.38s cubic-bezier(0.3, 1.3, 0.5, 1);
}
.forme-segmented label {
  position: relative;
  display: grid;
  place-items: center;
  height: 34px;
  padding: 0 16px;
  color: #8a8a93;
  white-space: nowrap;
  cursor: pointer;
  transition: color 0.2s;
}
.forme-segmented label:hover,
.forme-segmented label[data-active] {
  color: #f4f4f5;
}
.forme-segmented input {
  position: absolute;
  inset: 0;
  margin: 0;
  opacity: 0;
  cursor: inherit;
}
.forme-segmented label:has(input:focus-visible) {
  border-radius: 9px;
  outline: 2px solid #f4f4f5;
  outline-offset: 1px;
}
@media (prefers-reduced-motion: reduce) {
  .forme-segmented-thumb,
  .forme-segmented label {
    transition: none;
  }
}
